-- 고객이 관리자의 거점 범위에 있는지(BR-102): 전체 범위이거나, 그 거점 관할 주소가 있는 고객
CREATE OR REPLACE FUNCTION public.can_access_customer(p_customer bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.can_access_branch(NULL) OR EXISTS (
    SELECT 1 FROM customer_address ca
    WHERE ca.customer_id = p_customer AND ca.deleted_at IS NULL AND public.can_access_branch(ca.branch_id)
  )
$$;
--> statement-breakpoint
-- 고객 화면(A-CUS-010)·상담 콘솔(A-CSL-010) 권한이 있으면 거점 범위 안의 고객·주소를 조회
CREATE POLICY customer_select_cus ON public.customer FOR SELECT TO authenticated
  USING ((public.has_permission('A-CUS-010', 'READ') OR public.has_permission('A-CSL-010', 'READ')) AND public.can_access_customer(id));
--> statement-breakpoint
CREATE POLICY customer_address_select_cus ON public.customer_address FOR SELECT TO authenticated
  USING ((public.has_permission('A-CUS-010', 'READ') OR public.has_permission('A-CSL-010', 'READ')) AND public.can_access_customer(customer_id));
--> statement-breakpoint
CREATE POLICY consent_history_select ON public.consent_history FOR SELECT TO authenticated
  USING (public.has_permission('A-CUS-020', 'READ') AND public.can_access_customer(customer_id));
--> statement-breakpoint
CREATE POLICY customer_tag_select ON public.customer_tag FOR SELECT TO authenticated
  USING (public.has_permission('A-CUS-020', 'READ') AND public.can_access_customer(customer_id));
--> statement-breakpoint
CREATE POLICY customer_tag_write ON public.customer_tag FOR ALL TO authenticated
  USING (public.has_permission('A-CUS-020', 'UPDATE') AND public.can_access_customer(customer_id))
  WITH CHECK (public.has_permission('A-CUS-020', 'UPDATE') AND public.can_access_customer(customer_id));
--> statement-breakpoint
-- 통화·상담: 상담 콘솔(A-CSL-010) 또는 상담 이력(A-CSL-070) 조회 권한 + 고객 거점 범위
CREATE POLICY call_log_select ON public.call_log FOR SELECT TO authenticated
  USING (public.has_permission('A-CSL-010', 'READ') AND (customer_id IS NULL OR public.can_access_customer(customer_id)));
--> statement-breakpoint
CREATE POLICY consultation_select ON public.consultation FOR SELECT TO authenticated
  USING ((public.has_permission('A-CSL-010', 'READ') OR public.has_permission('A-CSL-070', 'READ'))
    AND (customer_id IS NULL OR public.can_access_customer(customer_id)));
--> statement-breakpoint
-- 상담 스크립트: 상담 콘솔에서 읽고 A-CNT-050 권한으로 관리
CREATE POLICY consult_script_select ON public.consult_script FOR SELECT TO authenticated
  USING (public.has_permission('A-CSL-010', 'READ') OR public.has_permission('A-CNT-050', 'READ'));
--> statement-breakpoint
CREATE POLICY consult_script_insert ON public.consult_script FOR INSERT TO authenticated
  WITH CHECK (public.has_permission('A-CNT-050', 'CREATE'));
--> statement-breakpoint
CREATE POLICY consult_script_update ON public.consult_script FOR UPDATE TO authenticated
  USING (public.has_permission('A-CNT-050', 'UPDATE'));
--> statement-breakpoint
CREATE POLICY consult_script_delete ON public.consult_script FOR DELETE TO authenticated
  USING (public.has_permission('A-CNT-050', 'DELETE'));
--> statement-breakpoint
-- 배정: 주문을 볼 수 있으면 조회 (쓰기는 서버만)
