INSERT INTO public.consult_script (script_code, title, content, trigger_point) VALUES
  ('PRIVACY_CONSENT', '개인정보 수집·이용 동의', '원활한 출장 접수를 위해 고객님의 성함, 연락처, 방문 주소를 수집·이용합니다. 수집한 정보는 서비스 제공과 사후 관리에만 쓰고, 관련 법에 따른 보관 기간이 지나면 파기합니다. 동의하시겠습니까?', 'PRIVACY_CONSENT'),
  ('NIGHT_VISIT', '평일 야간 방문 안내', '평일 오후 6시 이후 방문은 야간 할증이 추가됩니다. 이 시간으로 약속을 잡아 드릴까요?', 'NIGHT_VISIT'),
  ('HOLIDAY_VISIT', '휴일 방문 안내', '토요일·일요일·공휴일 방문은 휴일 할증이 추가됩니다. 이 날짜로 약속을 잡아 드릴까요?', 'HOLIDAY_VISIT'),
  ('PURGE_REQUEST', '개인정보 파기 요청 응대', '요청하신 개인정보 파기는 진행 중인 예약이 없을 때 처리됩니다. 법에 따라 거래 기록은 정해진 기간 동안 보관 후 파기됩니다.', 'PURGE_REQUEST')
ON CONFLICT (script_code) DO NOTHING;
